class Cache:
    def __init__(self, ttl: float, clock: Optional[clock.Clock]) -> None:
        self._ttl = ttl
        self._clock = clock

    def set(self, key: str, value: Any) -> None:
        self[key] = value

    def get(self, key: str, default: Any = None) -> Any:
        return self[key] if key in self else default

    def _expire_at(self, key: str) -> float:
        return self._clock.now() + self._ttl

    def _refresh_expiry(self, key: str) -> None:
        self[key] = self[key]

